node --test tests/visible.test.mjs && node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import { LineReader, readLines } from './src/lines.mjs';
const encoder = new TextEncoder();
const utf8 = encoder.encode('A€😀\r\n\nB\rC\r');
const chunks = [...utf8].map(byte => Uint8Array.of(byte));
assert.deepEqual(await readLines(chunks), ['A€😀', '', 'B\rC\r']);
assert.deepEqual(await readLines([encoder.encode('x\n')]), ['x']);
assert.deepEqual(await readLines([encoder.encode('\n')]), ['']);
const reader = new LineReader();
assert.deepEqual(reader.feed(Uint8Array.of(0xe2, 0x82)), []);
assert.deepEqual(reader.feed(Uint8Array.of(0xac, 0x0a)), ['€']);
assert.deepEqual(reader.end(), []);
const invalid = new LineReader();
invalid.feed(Uint8Array.of(0xe2));
assert.deepEqual(invalid.end(), ['�']);
console.log('Additional streaming UTF-8 contract checks passed.');
EOF
